import{z as i,x as o,o as e,c as d,q as n,j as B,D as a,d as A,s as l,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"数值实验设计","description":"","frontmatter":{"title":"数值实验设计","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/num-experiment-design.md","filePath":"llm/num-experiment-design.md","lastUpdated":1791413859000}'),p={name:"llm/num-experiment-design.md"};function m(u,E,D,h,F,c){const r=o("Mermaid");return e(),d("div",null,[E[2]||(E[2]=n('<h1 id="数值实验设计" tabindex="-1">数值实验设计 <a class="header-anchor" href="#数值实验设计" aria-label="Permalink to &quot;数值实验设计&quot;">​</a></h1><div class="epigraph"><p>数值实验最难的不是跑，而是归因：你看到的差来自格式、来自舍入，还是仅仅来自另一条归约树。</p><footer>—— 据混合精度训练报告的消融口径与本课程前九课的记账框架整理</footer></div><p><a href="/llm/num-crosshardware-consistency">上一课</a>给跨硬件的迁移签下三层验收；前几课的每条结论——指数换尾数、尺子三代、SR 的方差、STE 的偏置、异常分型——都只有在设计正确的实验里才可信。本课写方法本身：一个数值实验怎么设计，结论才能写下「格式 A 优于格式 B」而不掺杂别的因素。训练运行的统计观（梯度噪声、batch 与方差的换算）见 <a href="/llm/gradient-noise-scale">梯度噪声尺度</a>；优化器状态怎么存见 <a href="/llm/adamw">AdamW</a>。本课不重复它们，只管实验的骨架。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>数值实验比普通消融难在三处。其一，开关不独立：改一个 dtype 可能同时改变速度、显存、数值噪声与溢出率——一次动两个轴，效应就归因不了。其二，随机种子钉不住非确定性：原子加、核调度、归约树的差异让同种子两次运行也不同，种子不再是唯一的随机源。其三，效应量小：格式变化对损失的常见效应量，与 run-to-run 方差同量级——单次运行看到的差，很可能只是噪声的名字。</p><p>三处共同指向一个失败模式：跑了很多实验，写下的结论是「我们觉得 BF16 加 FP8 通信更好」——没有对照组的口径，等于没说。</p><p><span class="marginnote">直觉类比：在颠簸的车上用体重秤称一枚硬币——空秤的读数晃动就有几克，硬币只有五克。单次读数说明不了任何事；要么配对消震（两次称量同起同落），要么多次读数取均值。实验设计干的就是这两件事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>骨架分五件。<strong>单轴开关表</strong>：把数值决策拆成五个独立开关——计算 dtype、通信 dtype、主权重格式、优化器状态精度、缩放策略（第一课起逐课定义的三个 dtype 在这里归位）；每次只动一个，其余钉在默认档。<strong>配对设计</strong>：同一数据顺序、同一初始化、同一拓扑下成对比较——数据顺序与初始化主导 run 间方差，配对把它们从比较中消掉。<strong>重复与功效</strong>：先估计同配置的 run 间方差，再决定重复次数与可分辨的最小效应；分不清「没效应」与「没功效」是设计失败。<strong>FP32 参照轨</strong>：每批实验保留一条宽格式同 schedule 的参照，所有窄格式结果相对它报告——没有参照轨，看不出联合漂移。<strong>前置判据</strong>：判停条件、主要指标、验收带在跑之前写下，防止事后挑选。</p>',9)),(e(),B(s,null,{default:a(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E9%97%AE%E9%A2%98%EF%BC%9A%E6%A0%BC%E5%BC%8F%20A%20%E6%98%AF%E5%90%A6%E5%8F%AF%E7%94%A8%22%5D%20--%3E%20VAR%5B%22%E4%BC%B0%20run%20%E9%97%B4%E6%96%B9%E5%B7%AE%EF%BC%9A%E5%AE%9A%E9%87%8D%E5%A4%8D%E6%95%B0%22%5D%0A%20%20VAR%20--%3E%20PAIR%5B%22%E9%85%8D%E5%AF%B9%EF%BC%9A%E5%90%8C%E6%95%B0%E6%8D%AE%E9%A1%BA%E5%BA%8F%E5%90%8C%E5%88%9D%E5%A7%8B%E5%8C%96%22%5D%0A%20%20PAIR%20--%3E%20AXIS%5B%22%E5%8D%95%E8%BD%B4%E5%BC%80%E5%85%B3%EF%BC%9A%E4%B8%80%E6%AC%A1%E5%8A%A8%E4%B8%80%E4%B8%AA%20dtype%22%5D%0A%20%20AXIS%20--%3E%20REF%5B%22FP32%20%E5%8F%82%E7%85%A7%E8%BD%A8%E5%B9%B6%E8%A1%8C%22%5D%0A%20%20REF%20--%3E%20REG%5B%22%E5%89%8D%E7%BD%AE%E5%88%A4%E6%8D%AE%EF%BC%9A%E4%B8%BB%E6%8C%87%E6%A0%87%E4%B8%8E%E9%AA%8C%E6%94%B6%E5%B8%A6%22%5D%0A%20%20REG%20--%3E%20REPORT%5B%22%E6%8A%A5%E5%91%8A%EF%BC%9A%E6%95%88%E5%BA%94%E9%87%8F%E5%8A%A0%E5%8C%BA%E9%97%B4%E5%8A%A0%E6%A0%BC%E5%BC%8F%E6%B8%85%E5%8D%95%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[A("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"配对为什么有效：run 间方差的主要成分是数据顺序与初始化（它们决定损失景观里从哪条谷下去），配对比较让两次运行共享这些成分，差值里只剩被测轴的效应与数值非确定性。五开关为什么不能一起动：开关之间有交互项——通信精度的影响取决于主权重格式（梯度在什么宽度上被累加回去），缩放策略的影响取决于计算 dtype；两个轴一起动，交互项会伪装成主效应，方向都能错。中间量插桩为什么是归因的钥匙：损失是积分量，amax 序列、溢出计数、update 与 weight 之比这些微分量才指得出故障在哪一层——第五课的图谱与第十一课的仪表盘都是插桩协议的特例。",-1)),(e(),B(s,null,{default:a(()=>[l(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8F%AA%E5%8A%A8%E8%AE%A1%E7%AE%97%20dtype%20%E9%80%9A%E4%BF%A1%E9%92%89%E4%BD%8F%22%5D%20--%3E%20R1%5B%22%E5%B7%AE%E5%80%BC%E5%8F%AF%E5%BD%92%E5%9B%A0%E5%88%B0%E8%AE%A1%E7%AE%97%22%5D%0A%20%20B%5B%22%E5%90%8C%E6%97%B6%E5%8A%A8%E8%AE%A1%E7%AE%97%E4%B8%8E%E9%80%9A%E4%BF%A1%20dtype%22%5D%20--%3E%20R2%5B%22%E5%B7%AE%E5%80%BC%E6%B7%B7%E5%85%A5%E4%BA%A4%E4%BA%92%E9%A1%B9%22%5D%0A%20%20R2%20--%3E%20TRAP%5B%22%E4%BA%A4%E4%BA%92%E9%A1%B9%E4%BC%AA%E8%A3%85%E6%88%90%E4%B8%BB%E6%95%88%E5%BA%94%20%E6%96%B9%E5%90%91%E9%83%BD%E5%8F%AF%E8%83%BD%E9%94%99%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p>这张图回答「为什么开关一次只能动一个」：两个轴一起动，差值里既有主效应也有交互项（通信精度的影响取决于梯度在什么宽度上累加回去），交互项完全可以反号——这时写下的结论方向都是错的。</p><p><span class="marginnote">小模型上跑通的数值结论不能外推：异常通道的幅度与集中度随模型规模变（第五课），FP8 配方在 1B 上的溢出率不代表 70B。缩放验证是数值实验里少数「必须重跑」的类目。</span></p><p><span class="marginnote">术语翻译：配对设计就是「同卵双胞胎对照」——两次运行共享同一数据顺序、同一初始化、同一拓扑，唯一的差别是被测的那个开关，于是差值里剩下的成分只能归给它。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>三个易错点。速度不是正确性的证据：快了三倍与算得对是两个命题，验收表（第八、九课）没过之前不开香槟。记录要带格式清单：计算、通信、主权重、优化器状态、缩放策略五个字段写进每条实验记录——三个月后没人记得当时的 dtype 组合。非确定性要在报告里定性：同种子两次运行的散布测一次，写进误差棒；否则读者无法判断你的差是效应还是抖动。最后，数值实验的可重复性以「统计级重复」为标准，不以位级复刻为标准——位级只在自己跟自己比（第九课）时才有意义。</p><p><span class="marginnote">常见误区：把「快了 3 倍」写进数值正确性结论。速度是系统工程指标，算得对要验收表说话；快而错的配置，会在第一次异常输入溢出时连本带利还回去。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>五开关单轴消融：计算、通信、主权重、优化器状态、缩放策略，一次只动一个。</li><li>配对设计消掉数据顺序与初始化的 run 间方差；重复数由测得的方差决定。</li><li>FP32 参照轨是每批实验的锚；前置判据防事后挑选。</li><li>交互项会伪装成主效应；归因靠 amax、溢出计数、更新比这类微分量插桩。</li><li>结论外推受规模限制；报告必须带五字段格式清单与散布。</li><li>出处：混合精度训练报告的消融口径；本课程第一至九课的记账框架。</li></ul>',8))])}const _=i(p,[["render",m]]);export{g as __pageData,_ as default};
